//! hbbs key pair (`id_ed25519` + `id_ed25519.pub`), byte-compatible with
//! upstream rustdesk-server `gen_sk` (sodiumoxide/libsodium).
//!
//! `fixtures/hbbs-libsodium/` was generated by real libsodium through
//! PyNaCl's raw bindings with the upstream algorithm (see `gen_fixture.py`
//! there for the exact command): `id_ed25519` is base64 of the 64-byte
//! libsodium secret key (seed || public key), `id_ed25519.pub` base64 of the
//! 32-byte public key, `signature.b64` a libsodium detached signature of
//! `message.txt`.

#![allow(clippy::unwrap_used, clippy::panic)]

use std::path::{Path, PathBuf};

use base64_022::Engine as _;
use base64_022::engine::general_purpose::STANDARD;
use deskhaven_core::keys::{
    KeyError, KeyWarning, SignalKeyPaths, load_or_generate_signal_key, read_signal_key,
};
use ed25519_dalek::{Signature, Verifier, VerifyingKey};

const FIXTURE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/hbbs-libsodium");

fn fixture(name: &str) -> String {
    std::fs::read_to_string(Path::new(FIXTURE).join(name)).unwrap()
}

#[cfg(unix)]
fn mode(path: &Path) -> u32 {
    use std::os::unix::fs::PermissionsExt;
    std::fs::metadata(path).unwrap().permissions().mode() & 0o7777
}

#[cfg(unix)]
fn set_mode(path: &Path, mode: u32) {
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode)).unwrap();
}

/// Copies the libsodium fixture into `dir` the way an operator copies an
/// OSS hbbs key (private key 0600).
fn install_fixture(dir: &Path) -> SignalKeyPaths {
    let paths = SignalKeyPaths::resolve(Path::new(""), dir);
    std::fs::write(paths.secret(), fixture("id_ed25519")).unwrap();
    std::fs::write(paths.public(), fixture("id_ed25519.pub")).unwrap();
    #[cfg(unix)]
    set_mode(paths.secret(), 0o600);
    paths
}

fn verifying_key(pub_b64: &str) -> VerifyingKey {
    let bytes: [u8; 32] = STANDARD.decode(pub_b64.trim()).unwrap().try_into().unwrap();
    VerifyingKey::from_bytes(&bytes).unwrap()
}

#[test]
fn paths_default_to_data_dir_and_append_pub() {
    let default = SignalKeyPaths::resolve(Path::new(""), Path::new("/srv/dh"));
    assert_eq!(default.secret(), Path::new("/srv/dh/id_ed25519"));
    assert_eq!(default.public(), Path::new("/srv/dh/id_ed25519.pub"));

    let custom = SignalKeyPaths::resolve(Path::new("/etc/keys/hbbs"), Path::new("/srv/dh"));
    assert_eq!(custom.secret(), Path::new("/etc/keys/hbbs"));
    assert_eq!(custom.public(), Path::new("/etc/keys/hbbs.pub"));
}

#[test]
fn libsodium_key_files_load_with_the_same_public_key() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());

    let loaded = load_or_generate_signal_key(&paths).unwrap();

    assert!(loaded.warnings.is_empty(), "{:?}", loaded.warnings);
    assert_eq!(loaded.value.public_key_base64(), fixture("id_ed25519.pub"));
    // The 64-byte layout is libsodium's seed || public key, unchanged.
    let file_bytes = STANDARD.decode(fixture("id_ed25519")).unwrap();
    assert_eq!(
        loaded.value.keypair_bytes().as_slice(),
        file_bytes.as_slice()
    );
    assert_eq!(&file_bytes[32..], loaded.value.public_key().as_slice());
    // Loading never rewrites operator-provided files.
    assert_eq!(
        std::fs::read_to_string(paths.secret()).unwrap(),
        fixture("id_ed25519")
    );
    assert_eq!(
        std::fs::read_to_string(paths.public()).unwrap(),
        fixture("id_ed25519.pub")
    );
}

#[test]
fn signatures_match_libsodium_byte_for_byte() {
    let dir = tempfile::tempdir().unwrap();
    let pair = load_or_generate_signal_key(&install_fixture(dir.path()))
        .unwrap()
        .value;
    let message = fixture("message.txt");

    let ours = pair.sign(message.as_bytes());

    // Ed25519 is deterministic: identical keys yield identical signatures.
    assert_eq!(STANDARD.encode(ours), fixture("signature.b64"));
    let vk = verifying_key(&fixture("id_ed25519.pub"));
    vk.verify(message.as_bytes(), &Signature::from_bytes(&ours))
        .unwrap();
}

#[test]
fn generates_upstream_format_in_fresh_data_dir() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("fresh").join("data");
    let paths = SignalKeyPaths::resolve(Path::new(""), &data_dir);

    let loaded = load_or_generate_signal_key(&paths).unwrap();

    assert!(loaded.warnings.is_empty(), "{:?}", loaded.warnings);
    let secret = std::fs::read_to_string(paths.secret()).unwrap();
    let public = std::fs::read_to_string(paths.public()).unwrap();
    // Standard padded base64, no trailing newline (upstream writes the bare string).
    assert_eq!(secret.len(), 88);
    assert!(secret.ends_with("=="));
    assert_eq!(public.len(), 44);
    assert!(public.ends_with('='));
    // Upstream rejects public keys containing '/' or ':' (exe-name config).
    assert!(!public.contains('/') && !public.contains(':'));
    assert_eq!(public, loaded.value.public_key_base64());
    let decoded = STANDARD.decode(&secret).unwrap();
    assert_eq!(&decoded[32..], STANDARD.decode(&public).unwrap().as_slice());

    let message = b"generated key signs";
    let signature = Signature::from_bytes(&loaded.value.sign(message));
    verifying_key(&public).verify(message, &signature).unwrap();
    #[cfg(unix)]
    {
        assert_eq!(mode(paths.secret()), 0o600);
        assert_eq!(mode(&data_dir), 0o700);
    }

    let again = load_or_generate_signal_key(&paths).unwrap();
    assert_eq!(again.value.public_key_base64(), public);
    assert_eq!(std::fs::read_to_string(paths.secret()).unwrap(), secret);
}

#[test]
fn mismatched_public_key_file_is_an_error_and_nothing_changes() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());
    let other = tempfile::tempdir().unwrap();
    let other_pub = {
        let p = SignalKeyPaths::resolve(Path::new(""), other.path());
        load_or_generate_signal_key(&p)
            .unwrap()
            .value
            .public_key_base64()
    };
    std::fs::write(paths.public(), &other_pub).unwrap();

    let err = load_or_generate_signal_key(&paths).unwrap_err();
    assert!(matches!(err, KeyError::PublicKeyMismatch { .. }), "{err:?}");
    assert!(matches!(
        read_signal_key(&paths).unwrap_err(),
        KeyError::PublicKeyMismatch { .. }
    ));
    assert_eq!(
        std::fs::read_to_string(paths.secret()).unwrap(),
        fixture("id_ed25519")
    );
    assert_eq!(std::fs::read_to_string(paths.public()).unwrap(), other_pub);
}

#[test]
fn public_key_file_with_surrounding_whitespace_matches() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());
    std::fs::write(paths.public(), format!("{}\n", fixture("id_ed25519.pub"))).unwrap();
    std::fs::write(paths.secret(), format!("{}\n", fixture("id_ed25519"))).unwrap();

    let loaded = load_or_generate_signal_key(&paths).unwrap();
    assert_eq!(loaded.value.public_key_base64(), fixture("id_ed25519.pub"));
}

#[test]
fn missing_public_key_file_is_recreated() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());
    std::fs::remove_file(paths.public()).unwrap();

    assert!(read_signal_key(&paths).unwrap().is_some());
    assert!(!paths.public().exists(), "read must not write");

    load_or_generate_signal_key(&paths).unwrap();
    assert_eq!(
        std::fs::read_to_string(paths.public()).unwrap(),
        fixture("id_ed25519.pub")
    );
}

#[test]
fn orphan_public_key_file_blocks_generation() {
    let dir = tempfile::tempdir().unwrap();
    let paths = SignalKeyPaths::resolve(Path::new(""), dir.path());
    std::fs::write(paths.public(), fixture("id_ed25519.pub")).unwrap();

    let err = load_or_generate_signal_key(&paths).unwrap_err();

    assert!(matches!(err, KeyError::OrphanPublicKey { .. }), "{err:?}");
    assert!(!paths.secret().exists());
}

#[test]
fn secret_whose_public_half_does_not_match_its_seed_is_rejected() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());
    let mut bytes = STANDARD.decode(fixture("id_ed25519")).unwrap();
    bytes[40] ^= 0xff;
    std::fs::write(paths.secret(), STANDARD.encode(&bytes)).unwrap();
    std::fs::remove_file(paths.public()).unwrap();

    let err = load_or_generate_signal_key(&paths).unwrap_err();

    assert!(matches!(err, KeyError::InvalidSignalKey { .. }), "{err:?}");
    assert!(!format!("{err} {err:?}").contains(&STANDARD.encode(&bytes)[..20]));
}

#[test]
fn secret_with_wrong_length_or_encoding_is_rejected() {
    let dir = tempfile::tempdir().unwrap();
    let paths = SignalKeyPaths::resolve(Path::new(""), dir.path());
    for contents in [STANDARD.encode([1u8; 32]), "%%% not base64".to_owned()] {
        std::fs::write(paths.secret(), &contents).unwrap();
        let err = load_or_generate_signal_key(&paths).unwrap_err();
        assert!(matches!(err, KeyError::InvalidSignalKey { .. }), "{err:?}");
        assert!(!format!("{err}").contains(contents.as_str()));
        assert_eq!(std::fs::read_to_string(paths.secret()).unwrap(), contents);
    }
}

#[cfg(unix)]
#[test]
fn permissive_secret_key_warns_but_loads() {
    let dir = tempfile::tempdir().unwrap();
    let paths = install_fixture(dir.path());
    set_mode(paths.secret(), 0o640);

    let loaded = load_or_generate_signal_key(&paths).unwrap();

    assert_eq!(
        loaded.warnings,
        vec![KeyWarning::PermissiveMode {
            path: PathBuf::from(paths.secret()),
            mode: 0o640
        }]
    );
    assert_eq!(mode(paths.secret()), 0o640);
}

#[test]
fn read_signal_key_on_empty_dir_is_none_and_creates_nothing() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    let paths = SignalKeyPaths::resolve(Path::new(""), &data_dir);

    assert!(read_signal_key(&paths).unwrap().is_none());
    assert!(!data_dir.exists());
}

#[test]
fn debug_output_hides_the_secret() {
    let dir = tempfile::tempdir().unwrap();
    let pair = load_or_generate_signal_key(&install_fixture(dir.path()))
        .unwrap()
        .value;
    let debug = format!("{pair:?}");
    assert!(!debug.contains(&fixture("id_ed25519")[..20]), "{debug}");
    assert!(debug.contains(&fixture("id_ed25519.pub")), "{debug}");
}

#[test]
fn oversized_secret_key_file_is_refused() {
    let dir = tempfile::tempdir().unwrap();
    let paths = SignalKeyPaths::resolve(Path::new(""), dir.path());
    std::fs::write(paths.secret(), "A".repeat(4097)).unwrap();

    let err = load_or_generate_signal_key(&paths).unwrap_err();
    assert!(matches!(err, KeyError::TooLarge { .. }), "{err:?}");
}

#[test]
fn concurrent_first_start_agrees_on_one_key_pair() {
    let dir = tempfile::tempdir().unwrap();
    let paths = SignalKeyPaths::resolve(Path::new(""), &dir.path().join("data"));
    let keys: Vec<String> = std::thread::scope(|s| {
        let handles: Vec<_> = (0..8)
            .map(|_| {
                s.spawn(|| {
                    let loaded = load_or_generate_signal_key(&paths).unwrap();
                    assert!(loaded.warnings.is_empty(), "{:?}", loaded.warnings);
                    loaded.value.public_key_base64()
                })
            })
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).collect()
    });
    assert!(keys.windows(2).all(|w| w[0] == w[1]), "{keys:?}");
    assert_eq!(std::fs::read_to_string(paths.public()).unwrap(), keys[0]);
}

#[cfg(unix)]
mod unix {
    use std::os::unix::fs::symlink;

    use super::*;

    #[test]
    fn symlinked_secret_key_is_refused() {
        let dir = tempfile::tempdir().unwrap();
        let real = install_fixture(dir.path());
        let link = SignalKeyPaths::resolve(&dir.path().join("alias"), dir.path());
        symlink(real.secret(), link.secret()).unwrap();

        for err in [
            load_or_generate_signal_key(&link).unwrap_err(),
            read_signal_key(&link).unwrap_err(),
        ] {
            assert!(matches!(err, KeyError::Symlink { .. }), "{err:?}");
        }
    }

    #[test]
    fn symlinked_public_key_is_refused() {
        let dir = tempfile::tempdir().unwrap();
        let paths = install_fixture(dir.path());
        let target = dir.path().join("real.pub");
        std::fs::rename(paths.public(), &target).unwrap();
        symlink(&target, paths.public()).unwrap();

        let err = load_or_generate_signal_key(&paths).unwrap_err();
        assert!(matches!(err, KeyError::Symlink { .. }), "{err:?}");
    }

    #[test]
    fn world_writable_key_directory_warns() {
        let dir = tempfile::tempdir().unwrap();
        let keys = dir.path().join("keys");
        std::fs::create_dir(&keys).unwrap();
        let paths = install_fixture(&keys);
        set_mode(&keys, 0o777);

        let loaded = load_or_generate_signal_key(&paths).unwrap();

        assert_eq!(
            loaded.warnings,
            vec![KeyWarning::WritableDirectory {
                path: keys.clone(),
                mode: 0o777
            }]
        );
        let text = loaded.warnings[0].to_string();
        assert!(text.contains("0777") && text.contains("writable"), "{text}");
    }
}
